"""PulseProcess / MapFluidController against the real Pulse engine (no mocks)."""

import pytest

from viva_pulse.core import build_core
from viva_pulse.processes import VITALS, MapFluidController, PulseProcess
from viva_pulse.runtime import ENV_VAR, PulseNotFoundError, resolve_install_dir


def make_pulse(**config):
    return PulseProcess(config=config, core=build_core())


def test_initial_state_is_the_loaded_pulse_state():
    state = make_pulse().initial_state()
    # StandardMale@0s.json, as generated by this Pulse build.
    assert state["heart_rate_bpm"] == pytest.approx(72.0, abs=1.0)
    assert state["mean_arterial_pressure_mmHg"] == pytest.approx(95.3, abs=1.0)
    assert state["blood_volume_mL"] == pytest.approx(5487.0, abs=10.0)
    assert state["total_hemorrhaged_volume_mL"] == 0.0
    assert state["irreversible_state"] is False


def test_update_emits_pulse_readings():
    """Falsifies: an update emits a delta or a stale value instead of Pulse's current
    reading. (Port mapping is checked against independent engines in test_patients.)"""
    proc = make_pulse()
    controls = {"hemorrhage_severity": 0.5, "iv_rate_mL_per_min": 0.0}
    for _ in range(30):
        update = proc.update(controls, 1.0)
        assert set(update) == set(VITALS)
        assert update == dict(zip(VITALS, proc._engine.pull_data()[1:]))
    assert update["total_hemorrhaged_volume_mL"] > 0.0


def test_hemorrhage_lowers_blood_volume_and_raises_heart_rate():
    proc = make_pulse()
    start = proc.initial_state()
    controls = {"hemorrhage_severity": 0.8, "iv_rate_mL_per_min": 0.0}
    for _ in range(4):
        proc.update(controls, 60.0)
    end = proc._read_vitals()
    assert start["blood_volume_mL"] - end["blood_volume_mL"] > 500.0
    assert end["heart_rate_bpm"] > start["heart_rate_bpm"] + 5.0


def test_zero_severity_does_not_bleed():
    proc = make_pulse()
    start = proc.initial_state()
    for _ in range(2):
        proc.update({"hemorrhage_severity": 0.0, "iv_rate_mL_per_min": 0.0}, 30.0)
    end = proc._read_vitals()
    assert end["total_hemorrhaged_volume_mL"] == 0.0
    assert end["blood_volume_mL"] == pytest.approx(start["blood_volume_mL"], abs=20.0)


def test_iv_infusion_slows_blood_loss():
    def blood_volume_after(iv_rate):
        proc = make_pulse()
        proc.initial_state()
        for _ in range(3):
            proc.update({"hemorrhage_severity": 0.8, "iv_rate_mL_per_min": iv_rate}, 60.0)
        return proc._read_vitals()["blood_volume_mL"]

    assert blood_volume_after(200.0) - blood_volume_after(0.0) > 200.0


def _infuse(compound, rate_mL_per_min, seconds):
    """Blood volume (mL) and hemoglobin content (g) after an infusion, from a directly
    driven engine."""
    from viva_pulse.processes import _load_engine
    from viva_pulse.runtime import ensure_pulse_importable

    ensure_pulse_importable()
    from pulse.cdm.engine import SEDataRequest
    from pulse.cdm.patient_actions import SESubstanceCompoundInfusion
    from pulse.cdm.scalars import MassUnit, VolumePerTimeUnit, VolumeUnit

    engine = _load_engine("", "HumanAdultWholeBody", "StandardMale@0s.json",
                          [SEDataRequest.create_physiology_request("BloodVolume", unit=VolumeUnit.mL),
                           SEDataRequest.create_physiology_request("HemoglobinContent", unit=MassUnit.g)])
    infusion = SESubstanceCompoundInfusion()
    infusion.set_compound(compound)
    infusion.get_rate().set_value(rate_mL_per_min, VolumePerTimeUnit.mL_Per_min)
    infusion.get_bag_volume().set_value(10.0, VolumeUnit.L)
    engine.process_action(infusion)
    assert engine.advance_time_s(seconds)
    return engine.pull_data()[1:]


def test_infused_volume_does_not_depend_on_the_compound():
    """Falsifies the fluid-resuscitation root cause: Pulse adds infused volume at the
    commanded rate whatever the compound (DrugModel.cpp, IVToVenaCava flow source), and the
    compound only adds its substances. Equal rates of saline and whole blood must give the
    same blood volume (to 1e-4; they differ by about 1e-5 through downstream chemistry),
    while blood adds exactly the hemoglobin its compound file carries."""
    import json

    rate, seconds = 100.0, 300.0
    saline_volume, saline_hb = _infuse("Saline", rate, seconds)
    blood_volume, blood_hb = _infuse("Blood", rate, seconds)
    assert blood_volume == pytest.approx(saline_volume, rel=1e-4)

    compound = json.loads((resolve_install_dir("") / "bin" / "substances" / "compounds" / "Blood.json").read_text())
    g_per_dL = {c["Name"]: c["Concentration"]["ScalarMassPerVolume"] for c in compound["Component"]}
    assert all(g_per_dL[name]["Unit"] == "g/dL" for name in ("Hemoglobin", "Oxyhemoglobin"))
    infused_hb_g = (g_per_dL["Hemoglobin"]["Value"] + g_per_dL["Oxyhemoglobin"]["Value"]) / 100.0 * rate * seconds / 60.0
    assert blood_hb - saline_hb == pytest.approx(infused_hb_g, rel=0.01)


def test_rejects_unknown_compartment():
    with pytest.raises(ValueError, match="hemorrhage_compartment"):
        make_pulse(hemorrhage_compartment="Elbow")


@pytest.mark.parametrize("severity", [-0.1, 1.5])
def test_rejects_out_of_range_severity(severity):
    proc = make_pulse()
    proc.initial_state()
    with pytest.raises(ValueError, match="hemorrhage_severity"):
        proc.update({"hemorrhage_severity": severity, "iv_rate_mL_per_min": 0.0}, 1.0)


def test_rejects_negative_iv_rate():
    proc = make_pulse()
    proc.initial_state()
    with pytest.raises(ValueError, match="iv_rate"):
        proc.update({"hemorrhage_severity": 0.0, "iv_rate_mL_per_min": -5.0}, 1.0)


def test_missing_state_file_is_reported():
    proc = make_pulse(state_file="NoSuchPatient@0s.json")
    with pytest.raises(FileNotFoundError, match="NoSuchPatient"):
        proc.initial_state()


def test_unknown_iv_compound_is_rejected_at_load():
    # Regression: Pulse segfaulted on the first infusion of a misspelled compound
    # (e.g. 508 s into a resuscitation run); it must fail when the engine loads.
    proc = make_pulse(iv_compound="Bloood")
    with pytest.raises(ValueError, match="Bloood"):
        proc.initial_state()


def test_shipped_compounds_load():
    for compound in ("Saline", "Blood"):
        assert make_pulse(iv_compound=compound).initial_state()["blood_volume_mL"] > 0


def test_explicit_bad_install_dir_raises_instead_of_falling_back(tmp_path):
    with pytest.raises(PulseNotFoundError, match="install_dir config"):
        resolve_install_dir(str(tmp_path))


def test_bad_env_install_dir_raises(tmp_path, monkeypatch):
    monkeypatch.setenv(ENV_VAR, str(tmp_path))
    with pytest.raises(PulseNotFoundError, match=ENV_VAR):
        resolve_install_dir()


@pytest.mark.parametrize(
    "map_mmHg, expected",
    [(95.0, 0.0), (90.0, 0.0), (86.0, 100.0), (50.0, 250.0)],
)
def test_map_fluid_controller(map_mmHg, expected):
    ctrl = MapFluidController(
        config={"target_map_mmHg": 90.0, "gain_mL_per_min_per_mmHg": 25.0,
                "max_rate_mL_per_min": 250.0},
        core=build_core(),
    )
    assert ctrl.update({"mean_arterial_pressure_mmHg": map_mmHg}) == {
        "iv_rate_mL_per_min": pytest.approx(expected)
    }
